package com.bank.strategy;

import java.math.BigDecimal;
import java.util.logging.Logger;

interface FeeStrategy { BigDecimal fee(BigDecimal amount); } // the algorithm

class FlatFee implements FeeStrategy {
    private final BigDecimal flat;
    FlatFee(BigDecimal flat) { this.flat = flat; }
    public BigDecimal fee(BigDecimal amount) { return flat; }
}

class PercentageFee implements FeeStrategy {
    private final BigDecimal percent;
    PercentageFee(BigDecimal percent) { this.percent = percent; }
    public BigDecimal fee(BigDecimal amount) {
        return amount.multiply(percent).divide(new BigDecimal("100"));
    }
}

class FeeContext {
    private final FeeStrategy strategy;             // no if-else; holds a strategy
    FeeContext(FeeStrategy strategy) { this.strategy = strategy; }
    BigDecimal computeFee(BigDecimal amount) { return strategy.fee(amount); }
}

public class StrategyDemo {
    public static void main(String[] args) {
        Logger log = Logger.getLogger("FEE");
        FeeContext rajesh = new FeeContext(new FlatFee(new BigDecimal("50")));
        FeeContext priya  = new FeeContext(new PercentageFee(new BigDecimal("0.5")));
        log.info("Rajesh fee = " + rajesh.computeFee(new BigDecimal("20000")));
        log.info("Priya fee = " + priya.computeFee(new BigDecimal("100000")));
    }
}
